INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass LED-Bildschirme immer teurer als LCDs sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Preise variieren je nach Modell"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen LED-Bildschirm für IT-Arbeit auswähle?', 3, '[{"text": "Kontrastverhältnis", "correct": true, "because": "Wichtig für Sichtbarkeit"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Rahmenfarbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen LED-Bildschirme für IT-Zwecke nützlich?', 5, '[{"text": "Hohe Energieeffizienz", "correct": true, "because": "Senkt Stromverbrauch"}, {"text": "Guter Schwarzwert", "correct": true, "because": "Verbessert Bildqualität"}, {"text": "Hohe Latenz", "correct": false, "because": "Nachteil"}, {"text": "Schwere Bauweise", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) LEDs nutzen Leuchtdioden. b) Sie haben immer schlechtere Farben als LCDs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "LEDs bieten oft bessere Farben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen LED-Bildschirm für Programmierung auswähle?', 4, '[{"text": "Auflösung", "correct": false, "because": "Wichtig für Lesbarkeit"}, {"text": "Reaktionszeit", "correct": false, "because": "Beeinflusst Darstellung"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob LED-Bildschirme immer heller als LCDs sind?', 2, '[{"text": "Ja", "correct": true, "because": "LEDs bieten oft höhere Helligkeit"}, {"text": "Nein", "correct": false, "because": "Abhängig von Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich einen LED-Bildschirm für IT-Schulungen nutze?', 3, '[{"text": "Hohe Bildqualität", "correct": true, "because": "Fördert Verständnis"}, {"text": "Geringes Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Maximale Lautstärke", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei einem LED-Bildschirm für Netzwerküberwachung entscheidend?', 5, '[{"text": "Hohe Auflösung", "correct": true, "because": "Zeigt Details"}, {"text": "Schnelle Reaktionszeit", "correct": true, "because": "Wichtig für Echtzeit"}, {"text": "Schwere Bauweise", "correct": false, "because": "Nicht erwünscht"}, {"text": "Geringe Farbtiefe", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) LED-Bildschirme sparen Energie. b) Sie sind immer größer als LCDs. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Größe variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich einen LED-Bildschirm für IT-Arbeit auswähle?', 4, '[{"text": "Hohe Farbgenauigkeit", "correct": false, "because": "Wichtig für Darstellung"}, {"text": "Gute Helligkeit", "correct": false, "because": "Fördert Sichtbarkeit"}, {"text": "Designer-Look", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Haben LED-Bildschirme immer eine längere Lebensdauer als LCDs?', 3, '[{"text": "Ja", "correct": true, "because": "LEDs halten oft länger"}, {"text": "Nein", "correct": false, "because": "Abhängig von Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein LED-Bildschirm für IT-Administration?', 4, '[{"text": "Geringer Stromverbrauch", "correct": true, "because": "Senkt Betriebskosten"}, {"text": "Hoher Kontrast", "correct": true, "because": "Verbessert Lesbarkeit"}, {"text": "Hohe Lautstärke", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass LED-Bildschirme keine Hintergrundbeleuchtung brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "LEDs sind die Hintergrundbeleuchtung"}, {"text": "Ja", "correct": false, "because": "Verwechslung mit OLED"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um einen LED-Bildschirm für IT-Tests auszuwählen?', 3, '[{"text": "Schnelle Reaktionszeit", "correct": true, "because": "Wichtig für Echtzeit"}, {"text": "Großer Bildschirm", "correct": false, "because": "Nicht primär"}, {"text": "Leichtbauweise", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) LED-Bildschirme bieten besseren Schwarzwert als LCDs. b) Sie sind immer teurer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei einem LED-Bildschirm für Programmierung?', 5, '[{"text": "Hohe Auflösung", "correct": true, "because": "Fördert Lesbarkeit"}, {"text": "Gute Farbwiedergabe", "correct": true, "because": "Wichtig für UI-Tests"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Rahmenfarbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einen LED-Bildschirm für IT-Schulungen kaufe?', 3, '[{"text": "Bildwiederholrate", "correct": false, "because": "Wichtig für Flüssigkeit"}, {"text": "Helligkeit", "correct": false, "because": "Fördert Sichtbarkeit"}, {"text": "Beleuchtungsstil", "correct": true, "because": "Ästhetisch, nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind LED-Bildschirme immer flimmerfrei?', 3, '[{"text": "Nein", "correct": true, "because": "Flimmern modellabhängig"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob LEDs für Statusanzeigen in Servern genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Zeigen Betriebszustände"}, {"text": "Nein", "correct": false, "because": "Häufig verwendet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist entscheidend, wenn ich einen LED-Bildschirm für IT-Entwicklung kaufe?', 4, '[{"text": "Hohe Farbgenauigkeit", "correct": true, "because": "Wichtig für Design"}, {"text": "Geringes Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]');
